import { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import FormLayout from "./FormLayout";
export default function AddUser() {
  const [name, setName] = useState("");
  const [address, setAddress] = useState("");
  const navigate = useNavigate();
  const save = async () => {
    const mobile = localStorage.getItem("mobile");
    if (!name || !address) return alert("Enter all details");
    await axios.post(
      `http://localhost:8080/otp/addUser?mobile=${mobile}&name=${name}&address=${address}`
    );
    localStorage.removeItem("mobile");
    navigate("/categories");
  };
  return (
    <FormLayout title="Add User Details" rightText="Complete Your Profile">
      <input
        className="form-control mb-3"
        placeholder="Enter name"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />
      <input
        className="form-control mb-3"
        placeholder="Enter address"
        value={address}
        onChange={(e) => setAddress(e.target.value)}
      />
      <button className="btn btn-dark w-100" onClick={save}>
        Save
      </button>
    </FormLayout>
  );
}
